insert into public.assets(id,organization_id,asset_type,name) values ('aaaaaaaa-0000-4000-8000-000000000001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','vehicle','Van A'),('aaaaaaaa-0000-4000-8000-000000000002','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','vehicle','No mileage'),('bbbbbbbb-0000-4000-8000-000000000001','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','vehicle','Van B');
set local role authenticated;
select set_config('request.jwt.claims', '{"sub": "11111111-1111-4111-8111-111111111111", "role": "authenticated", "organization_id": "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}', true);
select lives_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id": "cccccccc-0000-4000-8000-000000000001", "action": "baseline", "observed_at": "2020-01-01T00:00:00Z", "physical": "10000", "baseline_usage": "10000", "unit": "mi"}'::jsonb)$$, 'Initialize logical mileage');
select lives_ok($$select public.save_maintenance('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null,'{"id": "dddddddd-0000-4000-8000-000000000001", "expected_version": 0, "name": "Oil", "distance_interval": 1000, "distance_unit": "mi", "time_interval": null, "time_unit": null, "upcoming_percent": 10, "due_percent": 5, "enabled": true}'::jsonb)$$, 'Owner creates distance template');
select lives_ok($$select public.save_maintenance('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null,'{"id": "dddddddd-0000-4000-8000-000000000002", "expected_version": 0, "name": "Inspection", "distance_interval": null, "distance_unit": null, "time_interval": 6, "time_unit": "months", "upcoming_percent": 10, "due_percent": 5, "enabled": true}'::jsonb)$$, 'Owner creates time-only template');
select lives_ok($$select public.save_maintenance('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null,'{"id": "dddddddd-0000-4000-8000-000000000003", "expected_version": 0, "name": "Combined", "distance_interval": 1000, "distance_unit": "mi", "time_interval": 1, "time_unit": "years", "upcoming_percent": 10, "due_percent": 5, "enabled": true}'::jsonb)$$, 'Owner creates combined template');
select lives_ok($$select public.save_maintenance('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"id": "eeeeeeee-0000-4000-8000-000000000001", "expected_version": 0, "name": "Oil", "distance_interval": 1000, "distance_unit": "mi", "time_interval": null, "time_unit": null, "upcoming_percent": 10, "due_percent": 5, "template_id": "dddddddd-0000-4000-8000-000000000001", "next_due_usage": 10500, "next_due_date": null, "paused": false}'::jsonb)$$, 'Assign distance with explicit target');
select lives_ok($$select public.save_maintenance('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"id": "eeeeeeee-0000-4000-8000-000000000002", "expected_version": 0, "name": "Inspection", "distance_interval": null, "distance_unit": null, "time_interval": 6, "time_unit": "months", "upcoming_percent": 10, "due_percent": 5, "template_id": "dddddddd-0000-4000-8000-000000000002", "next_due_usage": null, "next_due_date": "2026-10-01", "paused": false}'::jsonb)$$, 'Calendar-only assignment requires no meter');
select lives_ok($$select public.save_maintenance('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"id": "eeeeeeee-0000-4000-8000-000000000003", "expected_version": 0, "name": "Combined", "distance_interval": 1000, "distance_unit": "mi", "time_interval": 1, "time_unit": "years", "upcoming_percent": 10, "due_percent": 5, "template_id": "dddddddd-0000-4000-8000-000000000003", "next_due_usage": 9900, "next_due_date": "2026-10-01", "paused": false}'::jsonb)$$, 'Combined assignment may start already overdue');
select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id":"cccccccc-0000-4000-8000-000000000002","action":"reading","observed_at":"2020-12-01T12:00:00Z","physical":"20000"}');
-- Helpers use invoker rights, so every assertion still exercises authenticated RLS/RPC access.
create function pg_temp.service(n integer, changes jsonb default '{}') returns uuid language sql as $$
  select public.save_service('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001',
    jsonb_build_object('command_id',case when changes ? 'expected_version' then gen_random_uuid()::text else 'f0000000-0000-4000-8000-'||lpad(n::text,12,'0') end,
      'id','f0000000-0000-4000-8000-'||lpad(n::text,12,'0'),'expected_version',0,'action','save','reason',null,
      'service_date','2020-02-01','title','Service','provider',null,'cost_cents',null,'currency','USD','notes',null,'total_distance',null,'schedule_ids','[]'::jsonb) || changes);
$$;
create function pg_temp.void_service(n integer, v integer) returns uuid language sql as $$
  select public.save_service('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001',
    jsonb_build_object('command_id',gen_random_uuid(),'id','f0000000-0000-4000-8000-'||lpad(n::text,12,'0'),'expected_version',v,'action','void','reason','Duplicate entry'));
$$;
select lives_ok($$select pg_temp.service(1)$$,'Unknown mileage and cost are allowed without satisfying maintenance');
select is((select next_due_usage from public.maintenance_assignments where name='Oil'),10500::numeric,'Unlinked service leaves targets alone');
select lives_ok($$select pg_temp.service(2,'{"total_distance":"10500","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001","eeeeeeee-0000-4000-8000-000000000002","eeeeeeee-0000-4000-8000-000000000003"]}')$$,'Backdated service between readings satisfies multiple schedules atomically');
select is((select next_due_usage from public.maintenance_assignments where name='Oil'),11500::numeric,'Distance advances from total distance at service');
select is((select next_due_date::text from public.maintenance_assignments where name='Inspection'),'2020-08-01','Time advances from service date');
select is((select next_due_usage from public.maintenance_assignments where name='Combined'),11500::numeric,'Combined distance advances');
select is((select next_due_date::text from public.maintenance_assignments where name='Combined'),'2021-02-01','Combined time advances');
select is((select count(*)::integer from public.service_schedule_effects),3,'Each target change has an audit entry');
select lives_ok($$select pg_temp.service(2,'{"total_distance":"10500","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001","eeeeeeee-0000-4000-8000-000000000002","eeeeeeee-0000-4000-8000-000000000003"]}')$$,'Retry is idempotent');
select is((select count(*)::integer from public.service_schedule_effects),3,'Retry cannot advance twice');
select throws_ok($$select pg_temp.service(2,'{"title":"Different"}')$$,'PT409',null,'Command reuse with changed input rejected');
select lives_ok($$select pg_temp.service(2,'{"expected_version":1,"reason":"Correct date and mileage","service_date":"2020-03-01","total_distance":"11000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001","eeeeeeee-0000-4000-8000-000000000002","eeeeeeee-0000-4000-8000-000000000003"]}')$$,'Latest service correction reverses then reapplies effects');
select is((select next_due_usage from public.maintenance_assignments where name='Oil'),12000::numeric,'Correction recalculates mileage');
select is((select next_due_date::text from public.maintenance_assignments where name='Inspection'),'2020-09-01','Correction recalculates time');
select lives_ok($$select pg_temp.void_service(2,2)$$,'Latest service can be voided');
select is((select next_due_usage from public.maintenance_assignments where name='Oil'),10500::numeric,'Void restores original target');
select is((select count(*)::integer from public.service_schedule_effects),12,'Apply, reversal, correction, and void audit retained');
select ok((select voided from public.service_records where id='f0000000-0000-4000-8000-000000000002'),'Voided record retained');
select throws_ok($$select pg_temp.void_service(2,3)$$,'PT409',null,'Voided records cannot be mutated again');
select lives_ok($$select pg_temp.service(3,'{"service_date":"2020-04-01","total_distance":"12000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001"]}')$$,'First subsequent completion');
select lives_ok($$select pg_temp.service(4,'{"service_date":"2020-06-01","total_distance":"14000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001"]}')$$,'Later completion');
select throws_ok($$select pg_temp.void_service(3,1)$$,'PT409',null,'Older service cannot undo later completion');
select throws_ok($$select pg_temp.service(3,'{"expected_version":1,"reason":"Remove effect","service_date":"2020-04-01","total_distance":"12000"}')$$,'PT409',null,'Removing older effect cannot corrupt history');
select lives_ok($$select pg_temp.service(3,'{"expected_version":1,"reason":"Shop spelling","provider":"Shop","service_date":"2020-04-01","total_distance":"12000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001"]}')$$,'Descriptive edits remain possible after later completion');
create temporary table before_backdated_conflict as
  select (select count(*) from public.service_records) as records,
    (select count(*) from public.service_revisions) as revisions,
    (select count(*) from public.service_schedule_effects) as effects,
    (select version from public.maintenance_assignments where name='Oil') as schedule_version;
select throws_ok($$select pg_temp.service(5,'{"service_date":"2020-05-01","total_distance":"13000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001"]}')$$,'PT409','Backdated service cannot overwrite later maintenance; save without schedule effects','Backdated completion cannot overwrite later service without asking PostgREST to retry');
select is((select count(*)::integer from public.service_records where id='f0000000-0000-4000-8000-000000000005'),0,'Rejected completion leaves no partial record');
select is((select count(*) from public.service_records),(select records from before_backdated_conflict),'Conflict rolls back the service record');
select is((select count(*) from public.service_revisions),(select revisions from before_backdated_conflict),'Conflict rolls back the audit revision');
select is((select count(*) from public.service_schedule_effects),(select effects from before_backdated_conflict),'Conflict leaves prior effect history intact');
select is((select version from public.maintenance_assignments where name='Oil'),(select schedule_version from before_backdated_conflict),'Conflict leaves schedule version intact');
select lives_ok($$select pg_temp.service(5,'{"service_date":"2020-05-01","total_distance":"13000"}')$$,'Same historical service can be saved without effects');
select is((select next_due_usage from public.maintenance_assignments where name='Oil'),15000::numeric,'Later service target preserved');
select throws_ok($$select pg_temp.service(6,'{"total_distance":"9999"}')$$,'23514',null,'Historical distance below prior reading rejected');
select throws_ok($$select pg_temp.service(6,'{"total_distance":"20001"}')$$,'23514',null,'Historical distance above later reading rejected');
select throws_ok($$select pg_temp.service(6,'{"service_date":"2010-01-01","total_distance":"100"}')$$,'23514',null,'Distance before baseline rejected');
select lives_ok($$select pg_temp.service(6,'{"service_date":"2010-01-01"}')$$,'Pre-baseline service allowed with unknown mileage');
select throws_ok($$select pg_temp.service(7,'{"schedule_ids":["eeeeeeee-0000-4000-8000-000000000003"]}')$$,'23514',null,'Combined schedule requires mileage');
select throws_ok($$select pg_temp.service(7,'{"service_date":"2999-01-01"}')$$,'22023',null,'Future completion rejected');
select throws_ok($$select pg_temp.service(7,'{"total_distance":"123.45"}')$$,'22023',null,'Excess distance precision rejected');
select throws_ok($$select pg_temp.service(7,'{"cost_cents":1.5}')$$,'22023',null,'Fractional cents rejected');
select throws_ok($$select pg_temp.service(7,'{"currency":"EUR"}')$$,'23514',null,'USD-only enforced in database');
select throws_ok($$select pg_temp.service(7,'{"organization_id":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}')$$,'22023',null,'Tenant ownership cannot be supplied in payload');
select throws_ok($$select pg_temp.service(7,'{"schedule_ids":["eeeeeeee-0000-4000-8000-000000000001","eeeeeeee-0000-4000-8000-000000000001"]}')$$,'22023',null,'Duplicate schedules rejected');
select lives_ok($$select pg_temp.service(7,'{"service_date":"2020-01-31","cost_cents":0,"schedule_ids":["eeeeeeee-0000-4000-8000-000000000002"]}')$$,'Calendar-only service accepts unknown mileage');
select is((select next_due_date::text from public.maintenance_assignments where name='Inspection'),'2020-07-31','Calendar months use calendar arithmetic');
select lives_ok($$select pg_temp.service(10,'{"service_date":"2020-08-31","schedule_ids":["eeeeeeee-0000-4000-8000-000000000002"]}')$$,'Month-end service recorded');
select is((select next_due_date::text from public.maintenance_assignments where name='Inspection'),'2021-02-28','Calendar advancement clamps to end of month');
select throws_ok($$select public.save_service('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000002','{"command_id":"f0000000-0000-4000-8000-000000000099","id":"f0000000-0000-4000-8000-000000000099","action":"save","expected_version":0,"reason":null,"title":"Wrong vehicle","service_date":"2020-02-01","provider":null,"notes":null,"cost_cents":null,"currency":"USD","total_distance":null,"schedule_ids":["eeeeeeee-0000-4000-8000-000000000002"]}')$$,'P0002',null,'Schedule linkage cannot cross vehicles');
select throws_ok($$select pg_temp.service(11,'{"service_date":"2020-07-01","total_distance":"16000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001","ffffffff-ffff-4fff-8fff-ffffffffffff"]}')$$,'P0002',null,'Missing second schedule rejects entire completion');
select is((select next_due_usage from public.maintenance_assignments where name='Oil'),15000::numeric,'First schedule advancement rolled back on second schedule failure');
select is((select count(*)::integer from public.service_records where id='f0000000-0000-4000-8000-000000000011'),0,'Multi-schedule failure leaves no service record');
-- Corrections preserve recorded service distance and targets while flagging review.
select lives_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id":"cccccccc-0000-4000-8000-000000000003","action":"correct","entry_id":"cccccccc-0000-4000-8000-000000000001","expected_revision_id":"cccccccc-0000-4000-8000-000000000001","physical":"15000","baseline_usage":"15000","reason":"Correct baseline"}')$$,'Meter correction is allowed even when service becomes inconsistent');
select is((select total_distance from public.service_records where id='f0000000-0000-4000-8000-000000000003'),12000::numeric,'Original service distance preserved');
select ok((select inconsistent from public.service_mileage_reviews('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001') where id='f0000000-0000-4000-8000-000000000003'),'Inconsistency surfaced for review');
select is((select next_due_usage from public.maintenance_assignments where name='Oil'),15000::numeric,'Meter correction does not rewrite schedule targets');
select lives_ok($$select pg_temp.service(3,'{"expected_version":2,"reason":"Add notes","notes":"Needs mileage review","service_date":"2020-04-01","total_distance":"12000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001"]}')$$,'Descriptive edit preserves inconsistent original mileage');
-- Role and tenant boundaries, including direct table writes and audit visibility.
select throws_ok($$delete from public.service_records$$,'42501',null,'Authenticated users cannot hard-delete service history');
select throws_ok($$update public.service_records set title='Bypass'$$,'42501',null,'Direct service writes denied');
select throws_ok($$delete from public.service_schedule_effects$$,'42501',null,'Audit effects cannot be deleted directly');
select throws_ok($$delete from public.service_revisions$$,'42501',null,'Revisions cannot be deleted directly');
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
select ok((select count(*)>0 from public.service_records),'Read-only member sees service records');
select ok((select count(*)>0 from public.service_revisions),'Read-only member sees revision audit');
select ok((select count(*)>0 from public.service_schedule_effects),'Read-only member sees schedule effects');
select throws_ok($$select pg_temp.service(8)$$,'42501',null,'Read-only cannot create');
select throws_ok($$select pg_temp.void_service(4,1)$$,'42501',null,'Read-only cannot void');
select set_config('request.jwt.claims','{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated"}',true);
select is((select count(*)::integer from public.service_records),0,'Driver cannot read history');
select is((select count(*)::integer from public.service_revisions),0,'Driver cannot read revisions');
select is((select count(*)::integer from public.service_schedule_effects),0,'Driver cannot read effects');
select throws_ok($$select pg_temp.service(8)$$,'42501',null,'Driver cannot create');
select set_config('request.jwt.claims','{"sub":"77777777-7777-4777-8777-777777777777","role":"authenticated"}',true);
select is((select count(*)::integer from public.service_records),0,'Other organization cannot read service records');
select is((select count(*)::integer from public.service_revisions),0,'Other organization cannot read revisions');
select is((select count(*)::integer from public.service_schedule_effects),0,'Other organization cannot read effects');
select is((select count(*)::integer from public.service_mileage_reviews('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001')),0,'Mileage review RPC respects tenant RLS');
select throws_ok($$select pg_temp.service(8)$$,'42501',null,'Other organization cannot mutate history');
select set_config('request.jwt.claims','{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated"}',true);
select is((select count(*)::integer from public.service_records),0,'Revoked member cannot read');
select throws_ok($$select pg_temp.service(8)$$,'42501',null,'Revoked member cannot write');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select lives_ok($$select pg_temp.service(8,'{"cost_cents":12345,"provider":"Local shop"}')$$,'Admin can create service');
select lives_ok($$select pg_temp.service(8,'{"expected_version":1,"reason":"Correct title","title":"Repaired"}')$$,'Admin can edit service');
select throws_ok($$select pg_temp.service(8,'{"expected_version":1,"reason":"Stale edit"}')$$,'PT409',null,'Stale service edits rejected');
reset role;
update public.maintenance_assignments set version=version+1, updated_at=now(), next_due_usage=17000 where name='Oil';
set local role authenticated;
select throws_ok($$select pg_temp.void_service(4,1)$$,'PT409',null,'Manual schedule change prevents service reversal');
select throws_ok($$select pg_temp.service(9,'{"service_date":"2020-07-01","total_distance":"16000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001"]}')$$,'PT409',null,'Backdated service cannot overwrite a subsequent manual change');
select lives_ok($$select pg_temp.service(12,jsonb_build_object('service_date',(now() at time zone (select timezone from public.organizations where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'))::date::text,'total_distance','30000','schedule_ids',jsonb_build_array('eeeeeeee-0000-4000-8000-000000000001')))$$,'Current service can advance a manually edited schedule');
select lives_ok($$select pg_temp.void_service(12,1)$$,'Latest completion reverses to manual target');
select throws_ok($$select pg_temp.service(13,'{"service_date":"2020-07-01","total_distance":"16000","schedule_ids":["eeeeeeee-0000-4000-8000-000000000001"]}')$$,'PT409',null,'Reversal does not erase the historical manual-change barrier');
select is((select next_due_usage from public.maintenance_assignments where name='Oil'),17000::numeric,'Restored manual target remains protected');
select lives_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id":"cccccccc-0000-4000-8000-000000000004","action":"replacement","observed_at":"2021-01-01T12:00:00Z","physical":"100","old_final":"21000","reason":"New odometer"}')$$,'Replacement preserves logical accumulated distance');
select lives_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id":"cccccccc-0000-4000-8000-000000000005","action":"reading","observed_at":"2021-02-01T12:00:00Z","physical":"1100"}')$$,'Post-replacement reading recorded');
select lives_ok($$select pg_temp.service(14,'{"service_date":"2021-01-15","total_distance":"21500"}')$$,'Backdated service validates logical distance across replacement');
select throws_ok($$select pg_temp.service(15,'{"service_date":"2021-01-15","total_distance":"600"}')$$,'23514',null,'Physical odometer value cannot masquerade as accumulated distance');
select lives_ok($$select pg_temp.service(15,'{"service_date":"2021-01-01","total_distance":"20500"}')$$,'Date-only service does not invent ordering relative to same-day readings');
reset role;
select throws_ok($$insert into public.service_records(id,organization_id,asset_id,service_date,title,version,updated_by) values(gen_random_uuid(),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','aaaaaaaa-0000-4000-8000-000000000001','2020-01-01','Invalid tenant',1,'11111111-1111-4111-8111-111111111111')$$,'23503',null,'Composite FK enforces service tenant ownership even for privileged inserts');
update public.maintenance_assignments set paused=true where name='Combined';
set local role authenticated;
select throws_ok($$select pg_temp.service(16,'{"service_date":"2021-01-15","total_distance":"21500","schedule_ids":["eeeeeeee-0000-4000-8000-000000000003"]}')$$,'55000',null,'Paused schedules cannot accept completion');
reset role;
update public.maintenance_assignments set paused=false where name='Combined';
update public.maintenance_templates set enabled=false where name='Combined';
set local role authenticated;
select throws_ok($$select pg_temp.service(16,'{"service_date":"2021-01-15","total_distance":"21500","schedule_ids":["eeeeeeee-0000-4000-8000-000000000003"]}')$$,'55000',null,'Disabled schedules cannot accept completion');
reset role;
update public.assets set archived_at=now() where id='aaaaaaaa-0000-4000-8000-000000000001';
set local role authenticated;
select ok((select count(*)>0 from public.service_records),'Archived vehicles retain history');
select throws_ok($$select pg_temp.service(9)$$,'55000',null,'Archived vehicle rejects new service');
select throws_ok($$select pg_temp.void_service(8,2)$$,'55000',null,'Archived history is read-only');
select * from finish();
rollback;
